target.css:
:root {
  --clay: #c8845a;
  --clay-light: #f2e0d0;
  --clay-dark: #7a4828;
  --ash: #6b7c6e;
  --ash-light: #dde6de;
  --cream: #fdf6ee;
  --ink: #2e1f0f;
  --ink-muted: #7a6555;
  --badge-green: #3d6b4a;
  --badge-green-bg: #d4ebda;
  --divider: #d9c4b0;
}

article.commission-tag {
  width: 420px;
  background-color: var(--cream);
  border: 2px solid var(--clay);
  border-radius: 6px;
  overflow: hidden;
  margin: 0 auto;
}

.tag-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--clay);
  padding: 8px 14px;
}

.tag-studio {
  font-size: 13px;
  font-weight: 700;
  color: var(--cream);
  letter-spacing: 0.04em;
}

.tag-id {
  font-size: 12px;
  font-weight: 600;
  color: var(--clay-light);
  letter-spacing: 0.08em;
}

.tag-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  padding: 14px 16px;
}

.tag-piece {
  border-right: 1px solid var(--divider);
  padding-right: 14px;
}

.piece-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.2;
  margin: 0 0 6px 0;
}

.piece-sub {
  font-size: 11px;
  color: var(--ash);
  font-weight: 500;
  letter-spacing: 0.03em;
  margin: 0;
  line-height: 1.4;
}

.tag-specs {
  padding-left: 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.spec-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.spec-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.spec-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--ink);
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--ash-light);
  border-top: 1px solid var(--divider);
  padding: 8px 16px;
}

.status-badge {
  font-size: 11px;
  font-weight: 700;
  color: var(--badge-green);
  background-color: var(--badge-green-bg);
  border: 1px solid var(--badge-green);
  border-radius: 20px;
  padding: 3px 10px;
  letter-spacing: 0.04em;
}

.tag-price {
  font-size: 18px;
  font-weight: 700;
  color: var(--clay-dark);
}
